using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;

namespace AuthGateway
{
    public class ServiceIdentity
    {
        public string ServiceName { get; set; }
        public string SharedSecret { get; set; }
        public string[] AllowedEndpoints { get; set; }
    }

    public class TokenValidator
    {
        private readonly Dictionary<string, ServiceIdentity> _registry;

        public TokenValidator()
        {
            _registry = new Dictionary<string, ServiceIdentity>(StringComparer.Ordinal)
            {
                ["billing-service"] = new ServiceIdentity
                {
                    ServiceName = "billing-service",
                    SharedSecret = "k8s-secret-billing-2024x",
                    AllowedEndpoints = new[] { "/api/invoices", "/api/payments" }
                },
                ["admin-service"] = new ServiceIdentity
                {
                    ServiceName = "admin-service",
                    SharedSecret = "k8s-secret-admin-2024x",
                    AllowedEndpoints = new[] { "/api/admin/users", "/api/admin/config", "/api/admin/secrets" }
                }
            };
        }

        public ServiceIdentity ValidateAndResolve(string serviceName, string providedHmac, string requestPath)
        {
            // Normalize the service name for consistent lookup
            string normalizedName = NormalizeServiceIdentifier(serviceName);

            if (!_registry.TryGetValue(normalizedName, out var identity))
                return null;

            // Verify HMAC signature using the service's shared secret
            string expectedHmac = ComputeHmac(identity.SharedSecret, requestPath);
            if (!CryptographicEquals(expectedHmac, providedHmac))
                return null;

            return identity;
        }

        public bool IsEndpointAuthorized(ServiceIdentity identity, string requestPath)
        {
            // Normalize request path for comparison
            string normalizedPath = NormalizeRequestPath(requestPath);
            return identity.AllowedEndpoints.Any(ep => PathMatches(normalizedPath, ep));
        }

        private bool PathMatches(string normalizedPath, string endpoint)
        {
            // Enforce a path-segment boundary so that '/api/invoices_secret' does
            // NOT match '/api/invoices'. A path matches an allowed endpoint only
            // if it equals the endpoint or continues at a proper '/' segment.
            string ep = endpoint.ToLowerInvariant();
            if (normalizedPath.Equals(ep, StringComparison.Ordinal))
                return true;

            if (normalizedPath.StartsWith(ep, StringComparison.Ordinal))
            {
                // The character immediately after the prefix must be a segment separator.
                if (ep.EndsWith("/"))
                    return true;
                return normalizedPath.Length > ep.Length && normalizedPath[ep.Length] == '/';
            }

            return false;
        }

        private string NormalizeServiceIdentifier(string input)
        {
            // Apply Unicode NFC normalization then case-fold
            string normalized = input.Normalize(NormalizationForm.FormC);
            return normalized.ToLowerInvariant();
        }

        private string NormalizeRequestPath(string path)
        {
            // Decode and normalize the path
            string decoded = Uri.UnescapeDataString(path);
            // Apply NFKC normalization to canonicalize Unicode characters
            string normalized = decoded.Normalize(NormalizationForm.FormKC);
            return normalized.ToLowerInvariant();
        }

        private string ComputeHmac(string secret, string message)
        {
            // Normalize the message BEFORE computing HMAC to ensure consistency
            string normalizedMessage = NormalizeRequestPath(message);
            using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secret));
            byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(normalizedMessage));
            return Convert.ToBase64String(hash);
        }

        private bool CryptographicEquals(string a, string b)
        {
            if (a == null || b == null) return false;
            byte[] aBytes = Encoding.UTF8.GetBytes(a);
            byte[] bBytes = Encoding.UTF8.GetBytes(b);
            return CryptographicOperations.FixedTimeEquals(aBytes, bBytes);
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<TokenValidator>();
            var app = builder.Build();

            app.Use(async (context, next) =>
            {
                var validator = context.RequestServices.GetRequiredService<TokenValidator>();
                string serviceName = context.Request.Headers["X-Service-Name"].FirstOrDefault() ?? "";
                string hmacSig = context.Request.Headers["X-Service-HMAC"].FirstOrDefault() ?? "";
                string path = context.Request.Path.Value ?? "/";

                var identity = validator.ValidateAndResolve(serviceName, hmacSig, path);
                if (identity == null)
                {
                    context.Response.StatusCode = 401;
                    await context.Response.WriteAsync("Authentication failed");
                    return;
                }

                if (!validator.IsEndpointAuthorized(identity, path))
                {
                    context.Response.StatusCode = 403;
                    await context.Response.WriteAsync("Endpoint not authorized for this service");
                    return;
                }

                context.Items["ServiceIdentity"] = identity;
                await next();
            });

            app.MapGet("/api/admin/secrets", (HttpContext ctx) =>
            {
                return Results.Json(new { secrets = new[] { "DB_PASSWORD=hunter2", "API_KEY=sk-live-xxx" } });
            });

            app.MapGet("/api/invoices", (HttpContext ctx) =>
            {
                return Results.Json(new { invoices = new[] { "INV-001", "INV-002" } });
            });

            app.Run();
        }
    }
}
